records.old:
/* Keep Image detail card headings readable on light surfaces. */
html:not([data-portal-theme="dark"]) .portal-page:is(.portal-image-studio-detail, .portal-image-hub-detail) .portal-card-title {
  color: var(--portal-ink);
}

